input.proposed_solution:
Turn the cache into an LRU with a default capacity of 500: on a hit, delete and re-insert the key (Map keeps insertion order, so the first key is always the least recently used); after inserting a new key, evict the first key if the size exceeds the cap. Added an eviction-order test.

Patch (already applied in the repository snapshot):
```diff
--- a/src/memoize.js
+++ b/src/memoize.js
@@ -1,18 +1,29 @@
 // @ts-check

 /**
- * Memoize a single-argument function.
+ * Memoize a single-argument function with a bounded LRU cache.
+ * Map preserves insertion order, so the first key is the least recently used one.
  * @template K, V
  * @param {(key: K) => V} fn
+ * @param {number} [maxEntries]
  */
-export function memoize(fn) {
+export function memoize(fn, maxEntries = 500) {
   /** @type {Map<K, V>} */
   const cache = new Map();
   /** @param {K} key */
   return (key) => {
-    if (cache.has(key)) return /** @type {V} */ (cache.get(key));
+    if (cache.has(key)) {
+      const hit = /** @type {V} */ (cache.get(key));
+      cache.delete(key);
+      cache.set(key, hit);
+      return hit;
+    }
     const value = fn(key);
     cache.set(key, value);
+    if (cache.size > maxEntries) {
+      const oldest = cache.keys().next();
+      if (!oldest.done) cache.delete(oldest.value);
+    }
     return value;
   };
 }
--- a/test/memoize.test.js
+++ b/test/memoize.test.js
@@ -9,3 +9,15 @@
   assert.equal(f(2), 4);
   assert.equal(calls, 1);
 });
+
+test("evicts the least recently used entry", () => {
+  let calls = 0;
+  const f = memoize((x) => { calls++; return x; }, 2);
+  f(1); f(2);
+  f(1);          // 1 becomes most recent
+  f(3);          // evicts 2
+  f(1);          // still cached
+  assert.equal(calls, 3);
+  f(2);          // recomputed
+  assert.equal(calls, 4);
+});
```
